import type { Register, EngineInterface } from 'claude-code'
import { DEFAULT_WORDS, DEFAULT_PATHS, list, isPublished, findOverclaims, denyMessage, typedText } from './logic.js'

let words: string[] = DEFAULT_WORDS
let paths: string[] = DEFAULT_PATHS
let watchBrowser = true

const ALLOW = 'allowNext'

// The deny text, or undefined when the text may pass. A one-time allowance is used up here.
async function verdict($: EngineInterface, where: string, text: string): Promise<string | undefined> {
  const hits = findOverclaims(text, words)
  if (hits.length === 0) return undefined
  // When the store cannot be read, stop rather than let it through.
  const allowed = await $.store.get(ALLOW).catch(() => undefined)
  if (allowed === true) {
    await $.store.delete(ALLOW).catch(() => undefined)
    return undefined
  }
  return denyMessage(where, hits)
}

export const register: Register = (on, options) => {
  const o = (options ?? {}) as { words?: string; paths?: string; watchBrowser?: boolean }
  words = list(o.words, DEFAULT_WORDS)
  paths = list(o.paths, DEFAULT_PATHS)
  watchBrowser = o.watchBrowser !== false

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'overclaim-allow',
      description: 'Let the next overclaim through once (when the word is intended and the person agreed)',
    })
    return next(e)
  })

  on('command.run', { command: 'overclaim-allow' }, async $ => {
    await $.store.set(ALLOW, true)
    return { text: 'overclaim-guard: the next stopped write or post will pass once.' }
  })

  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    if (!isPublished(e.file_path, paths)) return next(e)
    const deny = await verdict($, e.file_path, e.content)
    return deny ? { deny } : next(e)
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'Edit' }, async ($, e, next) => {
    if (!isPublished(e.file_path, paths)) return next(e)
    const deny = await verdict($, e.file_path, e.new_string)
    return deny ? { deny } : next(e)
  }).catch(($, e, next) => next(e))

  // Posts typed or pasted through a browser tool (X, YouTube, a blog editor).
  on('tool.call', async ($, e, next) => {
    if (!watchBrowser || !/^mcp__.+__(computer|javascript_tool|form_input)$/.test(String(e.tool))) return next(e)
    const text = typedText(e.tool, e as unknown as Record<string, unknown>)
    if (!text) return next(e)
    const deny = await verdict($, 'text typed in the browser', text)
    return deny ? { deny } : next(e)
  }).catch(($, e, next) => next(e))
}

