// Pure decision functions. No engine calls here, so the tests can call them directly.

// Words that promise more than anyone measured. English and Japanese by default.
export const DEFAULT_WORDS = [
  '100%', 'guaranteed', 'guarantee', 'zero risk', 'never fails', 'always works', 'perfect', 'flawless', 'bulletproof',
  '完全', 'ゼロ', '確実', '絶対', '必ず', '爆速', '１００％', '100％',
]

// Where published writing usually lives. Matched against the path with forward slashes.
export const DEFAULT_PATHS = [
  '/content/', '/posts/', '/blog/', '/drafts/', '/newsletter/', '/announcements/', '/press/',
  '/public/*.html', '/site/*.md', 'README.md', 'CHANGELOG.md',
]

// A comma separated setting as a clean list; the default when empty.
export function list(setting, fallback) {
  const items = String(setting ?? '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
  return items.length ? items : fallback
}

// Whether a file is published writing: a pattern is a path fragment, and `*` matches within one folder level.
export function isPublished(filePath, patterns) {
  const p = String(filePath || '').replace(/\\/g, '/')
  return patterns.some((pat) => {
    if (!pat.includes('*')) return p.includes(pat)
    const re = new RegExp(pat.split('*').map((s) => s.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('[^/]*') + '$')
    return re.test(p)
  })
}

// Each overclaiming word found, with a little text around it (at most 8 hits).
export function findOverclaims(text, words) {
  const src = String(text || '')
  const lower = src.toLowerCase()
  const hits = []
  for (const w of words) {
    const needle = w.toLowerCase()
    let i = lower.indexOf(needle)
    while (i !== -1 && hits.length < 8) {
      const around = src.slice(Math.max(0, i - 16), i + w.length + 16).replace(/\s+/g, ' ')
      hits.push('"' + w + '" in: ' + around)
      i = lower.indexOf(needle, i + needle.length)
    }
  }
  return hits
}

// The message Claude reads when a write or a typed post is stopped.
export function denyMessage(where, hits) {
  return [
    'overclaim-guard: ' + where + ' promises more than was measured:',
    ...hits.map((h) => '  - ' + h),
    'Rewrite it with what was actually measured, or say what is not known. If the word is intended, ask the person, then run /overclaim-allow to let the next one through.',
  ].join('\n')
}

// The text a browser tool is about to type or paste, or '' when the call types nothing.
export function typedText(tool, input) {
  const t = String(tool || '')
  if (/__computer$/.test(t)) return input && input.action === 'type' ? String(input.text || '') : ''
  if (/__javascript_tool$/.test(t)) {
    const code = String((input && input.text) || '')
    return /insertText|ClipboardEvent|clipboardData|innerText\s*=|textContent\s*=|\.value\s*=/.test(code) ? code : ''
  }
  if (/__form_input$/.test(t)) return input && typeof input.value === 'string' ? input.value : ''
  return ''
}

